    if v is None or (isinstance(v, float) and pd.isna(v)) or pd.isna(v):
        return None
    s = str(v).strip()
    if not s:
        return None
    try:
        return pd.to_datetime(s, errors="raise").strftime("%Y-%m-%d")
    except Exception:
        for fmt in ("%Y/%m/%d", "%d-%m-%Y", "%m/%d/%Y", "%Y-%m-%dT%H:%M:%S"):
            try:
                return datetime.strptime(s, fmt).strftime("%Y-%m-%d")
            except Exception:
                pass
        return s


def norm_status(v):
    if v is None:
        return None
    try:
        if pd.isna(v):
            return None
    except Exception:
        pass
    if isinstance(v, bool):
        return "active" if v else "inactive"
    s = str(v).strip()
    if not s:
        return None
    low = s.lower()
    if low in ("true", "t", "yes", "y", "1", "active"):
        return "active"
    if low in ("false", "f", "no", "n", "0", "inactive"):
        return "inactive"
    return s


def norm_str(v):
    if v is None:
        return None
    try:
        if pd.isna(v):
            return None
    except Exception:
        pass
    s = str(v).strip()
    return s if s else None


def norm_id(v):
    if v is None:
        return None
    try:
        if pd.isna(v):
            return None
    except Exception:
        pass
    try:
        return int(float(str(v).strip()))
    except Exception:
        return None


# ---------- load ----------
a = pd.read_json("/data/source_a/users.json")
b = pd.read_csv("/data/source_b/users.csv")
c = pd.read_parquet("/data/source_c/users.parquet")

A = pd.DataFrame({
    "user_id": a["id"].map(norm_id),
    "name": a["full_name"].map(norm_str),
    "email": a["email"].map(norm_str),
    "created_date": a["registration_date"].map(norm_date),
    "status": a["status"].map(norm_status) if "status" in a.columns else None,
})
B = pd.DataFrame({
    "user_id": b["user_id"].map(norm_id),
    "name": b["name"].map(norm_str),
    "email": b["email_address"].map(norm_str),
    "created_date": b["created_at"].map(norm_date),
    "status": b["is_active"].map(norm_status) if "is_active" in b.columns else None,
})
C = pd.DataFrame({
    "user_id": c["userId"].map(norm_id),
    "name": c["userName"].map(norm_str),
    "email": c["email"].map(norm_str),
    "created_date": c["joined"].map(norm_date),
    "status": c["active"].map(norm_status) if "active" in c.columns else None,
})

sources = {"source_a": A, "source_b": B, "source_c": C}
FIELDS = ["name", "email", "created_date", "status"]

per_source = {}
for name in PRIORITY:
    df = sources[name]
    d = {}
    for _, row in df.iterrows():
        uid = row["user_id"]
        if uid is None:
            continue
        d[uid] = {f: row[f] for f in FIELDS}
    per_source[name] = d

all_ids = sorted(set().union(*[set(d.keys()) for d in per_source.values()]))

rows = []
conflicts = []
for uid in all_ids:
    row = {"user_id": uid}
    for f in FIELDS:
        vals = {}
        for name in PRIORITY:
            v = per_source[name].get(uid, {}).get(f)
            if v is not None:
                vals[name] = v
        selected = None
        for name in PRIORITY:  # priority order
            if name in vals:
                selected = vals[name]
                break
        row[f] = selected
        distinct = {str(v) for v in vals.values()}
        if len(vals) > 1 and len(distinct) > 1:
            conflicts.append({
                "user_id": int(uid),
                "field": f,
                "values": {k: vals[k] for k in PRIORITY if k in vals},
                "selected": selected,
            })
    rows.append(row)

merged = pd.DataFrame(rows, columns=["user_id", "name", "email", "created_date", "status"])
merged["user_id"] = merged["user_id"].astype("int64")
for col in ["name", "email", "created_date", "status"]:
    merged[col] = merged[col].astype(object).where(merged[col].notna(), None)

merged.to_parquet("/app/merged_users.parquet", index=False)

report = {"total_conflicts": len(conflicts), "conflicts": conflicts}
with open("/app/conflicts.json", "w") as fh:
    json.dump(report, fh, indent=2)

print(merged.dtypes)
print(merged.to_string())
print(json.dumps(report, indent=2))
